function UICookingFoodGetNode:FillSelf()
    local vo = CookingUtils.GetBattleCookingFoodVo(self._data.foodId)
    if not vo then
        return
    end

    CfUtils.FillText(self.TextName, vo.name)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.id)
    CfUtils.FillImage(self.Root.transform:Find("LeftPanel/GoodQuality"), StoreUtils.GetGoodsBgByQuality(goodsVo.quality))
    CfUtils.FillImage(self.Root.transform:Find("LeftPanel/GoodQuality/GoodQuality2"), StoreUtils.GetGoodsBgByQuality(goodsVo.quality))

    CfUtils.FillText(self.TextDesc, goodsVo.desc)

    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(vo.id))

    self:FillBuffDescs(vo)
end

function UICookingFoodGetNode:FillBuffDescs(vo)
    local t = {}
    local t1= CookingUtils.GetBattleFoodEffectDesc(vo.id)
    local t2 = CfUtils.Split(vo.desc, ";")
    --table.insert(t, t1[1])
    for k, v in pairs(t2) do
        table.insert(t, v)
    end

    for k, v in pairs(t) do
        local go = self.Content.transform:Find("buff"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Cell, self.Content)
            go.name = "buff"..k
        end
        local status = (k == 1 and 2 or 1)
        local rootGo = go.transform:Find("AnimRoot")
        CfUtils.SetUISwitchText(rootGo.transform:Find("TextdDesc"), status)
        CfUtils.SetUISwitchImage(rootGo.transform:Find("Area/ImgSquare"), status)

        CfUtils.FillText(rootGo.transform:Find("TextdDesc"), v)
        KTool.SetActive(go, true)
        CfUtils.PlayDelayShowAnimate(rootGo, k, nil, 1.1)
    end 
end

